La prioridad default es Medium para mantener backward compat.

private priorityToNumber(p: ContextPriority): number {
  const map = {
    [ContextPriority.Critical]: 4,
    [ContextPriority.High]: 3,
    [ContextPriority.Medium]: 2,
    [ContextPriority.Low]: 1,
  };
  return map[p];
}

private getSortedSources(): RegisteredSource[] {
  return [...this.sources].sort((a, b) => {
    const diff = this.priorityToNumber(b.priority) - this.priorityToNumber(a.priority);
    return diff !== 0 ? diff : a.insertionOrder - b.insertionOrder;
  });
}

