Permite crear una vista filtrada del contexto:

async collectContextAbove(minPriority: ContextPriority): Promise<ContextOutput> {
  const minNum = this.priorityToNumber(minPriority);
  const filteredSources = this.getSortedSources()
    .filter(({ priority }) => this.priorityToNumber(priority) >= minNum);

  const contexts: ContextData[] = [];
  for (const { source } of filteredSources) {
    try {
      const data = await source.collect();
      contexts.push(data);
    } catch (error) {
      console.error(`Error collecting context from ${source.getName()}:`, error);
    }
  }

  return {
    contextSpecVersion: this.specVersion,
    generatedAt: new Date().toISOString(),
    agent: this.agent,
    contexts,
  };
}

getSourceCount(): number {
  return this.sources.length;
}

